import yaml

with open('review_issues.yaml', 'r') as f:
    data = yaml.safe_load(f)

# Mark all open issues with round 6 action_items as in_progress
changed = []
for issue in data.get('issues', []):
    if issue.get('status') == 'open':
        # Check if this issue has been dispatched (has action_items for round 6 or is an open item)
        has_r6_action = any(
            a.get('round', 0) >= 5 and a.get('status') == 'open'
            for a in issue.get('action_items', [])
        )
        if has_r6_action:
            issue['status'] = 'in_progress'
            # Also mark the open action_items as in_progress
            for a in issue.get('action_items', []):
                if a.get('status') == 'open':
                    a['status'] = 'in_progress'
            changed.append(issue['id'])

print(f'Updated {len(changed)} issues to in_progress:')
for c in changed:
    print(f'  - {c}')

with open('review_issues.yaml', 'w') as f:
    yaml.dump(data, f, default_flow_style=False, allow_unicode=True, width=200, sort_keys=False)
"
